local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Stage the entire import before touching the catalogue or the character's path.
local P, Sharing = APR.PathSharingProtocol, APR.PathSharing
local L = LibStub("AceLocale-3.0"):GetLocale("APR")

local function Rewrite(data, mapping)
    local required = data.requiredRoute
    if type(required) == "string" then data.requiredRoute = mapping[required] or required
    elseif type(required) == "table" then
        for index, key in ipairs(required) do required[index] = mapping[key] or key end
    end
    for index, entry in ipairs(data.nextRoute or {}) do
        if type(entry) == "string" then data.nextRoute[index] = mapping[entry] or entry
        elseif type(entry) == "table" then entry.route = mapping[entry.route] or entry.route end
    end
end--[[APR_DIAG]]; Rewrite = APRTrace("APR-Core/features/group/PathSharingImport.lua:10:Rewrite#1", Rewrite)--[[/APR_DIAG]]

function Sharing:Prepare(packet)
    if not P.Packet(packet) or packet.client ~= APR:GetGameVersion() then return end
    local stage = { path = {}, imports = {}, missing = {}, mapping = {}, records = {}, definitions = {}, labels = {} }
    local reserved, labels = {}, {}
    for key, data in pairs(APR.RouteQuestStepList) do
        reserved[key] = true
        if type(data) == "table" and data.label then labels[data.label] = true end
    end
    local unavailable = {}
    for _, record in ipairs(packet.routes) do
        stage.records[record.key] = record
        if not record.custom then
            local definition = APR:GetRouteData(record.key)
            if not definition or APRData.CustomRoute and APRData.CustomRoute[record.key] then
                unavailable[record.key] = true
            else
                stage.mapping[record.key], stage.labels[record.key] = record.key, definition.label or record.key
                stage.definitions[record.key] = definition
            end
        else
            local key, label = record.key, record.label
            local saved = APRData.CustomRoute and APRData.CustomRoute[key]
            local same = saved and P.Equal(saved, record.data)
            if not same and (reserved[key] or labels[label]) then
                local index = 1
                repeat
                    key, label = record.key .. " (" .. index .. ")", record.label .. " (" .. index .. ")"
                    index = index + 1
                until not reserved[key] and not labels[label]
            end
            reserved[key], labels[label] = true, true
            stage.mapping[record.key], stage.labels[record.key] = key, label
            if not same then
                local data = P.Copy(record.data)
                if data.steps or data.scenarios then data.label = label else data = { steps = data, label = label } end
                stage.imports[record.key] = { key = key, data = data }
            else
                stage.definitions[key] = APR:GetRouteData(key)
            end
        end
    end
    -- Identical local parents must also be copied if their dependency is renamed.
    local remapped = true
    while remapped do
        remapped = false
        for _, record in ipairs(packet.routes) do
            if record.custom and not stage.imports[record.key] then
                local data = P.Copy(record.data)
                Rewrite(data, stage.mapping)
                if not P.Equal(data, record.data) then
                    local index, key, label = 1
                    repeat
                        key, label = record.key .. " (" .. index .. ")", record.label .. " (" .. index .. ")"
                        index = index + 1
                    until not reserved[key] and not labels[label]
                    reserved[key], labels[label] = true, true
                    stage.mapping[record.key], stage.labels[record.key] = key, label
                    data = APR:NormalizeCustomRouteDefinition(key, record.data)
                    data.label = label
                    stage.imports[record.key] = { key = key, data = data }
                    remapped = true
                end
            end
        end
    end
    -- Missing prerequisites propagate through the graph, including cycles.
    local changed = true
    while changed do
        changed = false
        for _, record in ipairs(packet.routes) do
            if not unavailable[record.key] then
                for _, key in ipairs(record.required) do
                    if unavailable[key] then unavailable[record.key], changed = true, true; break end
                end
            end
        end
    end
    for _, record in ipairs(packet.routes) do
        if unavailable[record.key] then
            stage.missing[#stage.missing + 1] = record.label
            stage.imports[record.key] = nil
        elseif stage.imports[record.key] then
            Rewrite(stage.imports[record.key].data, stage.mapping)
        end
    end
    for _, key in ipairs(packet.path) do
        if not unavailable[key] then stage.path[#stage.path + 1] = key end
    end
    stage.unavailable = unavailable
    return stage
end--[[APR_DIAG]]; Sharing.Prepare = APRTrace("APR-Core/features/group/PathSharingImport.lua:22:Sharing:Prepare#2", Sharing.Prepare)--[[/APR_DIAG]]

function Sharing:JoinIndex(packet, stage)
    local position = packet.position
    if not position or stage.unavailable[position.route] or not stage.mapping[position.route]
        or APR:IsTemporaryRouteActive() or APR.routeValidationPending or APR.routeValidationFailed then return end
    local inPath = false
    for _, key in ipairs(stage.path) do if key == position.route then inPath = true end end
    if not inPath then return end
    local key = stage.mapping[position.route]
    -- A not-yet-installed custom route is tested against its normalized definition
    -- after registration; no foreign effective counter is ever imported.
    local record = stage.records and stage.records[position.route]
    local definition = record and record.custom and APR:NormalizeCustomRouteDefinition(record.key, record.data)
        or APR:GetRouteData(key)
    if self.Fingerprint(definition) ~= position.fingerprint then return end
    if stage.imports[position.route] then return key, nil, true end
    if APR.CanStartRoute and not APR:CanStartRoute(key) then return end
    local steps = APR:GetRouteSteps(key)
    if position.id == "end" then return key, #steps + 1 end
    local found
    for index = 1, #steps do
        local progress = APR:GetGroupRouteProgress(key, index)
        if progress and progress.id == position.id then found = index; break end
    end
    if not found then return end
    while found <= #steps and APR:StepFilterQuestHandler(steps[found]) do found = found + 1 end
    return key, found
end--[[APR_DIAG]]; Sharing.JoinIndex = APRTrace("APR-Core/features/group/PathSharingImport.lua:114:Sharing:JoinIndex#3", Sharing.JoinIndex)--[[/APR_DIAG]]

function Sharing:CaptureImportContext(request)
    request.paths, request.path = APRCustomPath, APRCustomPath[APR.PlayerID]
    request.pathSnapshot = P.Copy(request.path or {})
    request.playerData = APRData[APR.PlayerID]
    request.catalogRevision = APR._routeLookupRevision
end--[[APR_DIAG]]; Sharing.CaptureImportContext = APRTrace("APR-Core/features/group/PathSharingImport.lua:142:Sharing:CaptureImportContext#4", Sharing.CaptureImportContext)--[[/APR_DIAG]]

function Sharing:ImportContextCurrent(request)
    return self:RequestCurrent(request) and not InCombatLockdown() and not APR.routeValidationPending
        and not APR.routeValidationFailed and not APR:IsTemporaryRouteActive()
        and APRCustomPath == request.paths and APRCustomPath[APR.PlayerID] == request.path
        and P.Equal(request.path or {}, request.pathSnapshot)
        and APRData[APR.PlayerID] == request.playerData and APR._routeLookupRevision == request.catalogRevision
end--[[APR_DIAG]]; Sharing.ImportContextCurrent = APRTrace("APR-Core/features/group/PathSharingImport.lua:149:Sharing:ImportContextCurrent#5", Sharing.ImportContextCurrent)--[[/APR_DIAG]]

